function isMatch(s, p) {
  const m = s.length;
  const n = p.length;
  let prev = new Array(n + 1).fill(false);
  prev[0] = true;
  for (let j = 1; j <= n; j++) {
    prev[j] = prev[j - 1] && p[j - 1] === '*';
  }
  for (let i = 1; i <= m; i++) {
    const curr = new Array(n + 1).fill(false);
    for (let j = 1; j <= n; j++) {
      if (p[j - 1] === '*') {
        curr[j] = curr[j - 1] || prev[j];
      } else if (p[j - 1] === '?' || p[j - 1] === s[i - 1]) {
        curr[j] = prev[j - 1];
      }
    }
    prev = curr;
  }
  return prev[n];
}

