function isMatch(s, p) {
  // Try every possible length for each star, remembering (i, j) results.
  const memo = new Map();
  const match = (i, j) => {
    if (j === p.length) return i === s.length;
    const key = i * (p.length + 1) + j;
    if (memo.has(key)) return memo.get(key);
    let result = false;
    if (p[j] === '*') {
      for (let k = i; k <= s.length && !result; k++) result = match(k, j + 1);
    } else if (i < s.length && (p[j] === '?' || p[j] === s[i])) {
      result = match(i + 1, j + 1);
    }
    memo.set(key, result);
    return result;
  };
  return match(0, 0);
}

