function generate(rand, size) {
  const large = size === 'large';
  const letters = large ? 'abc' : 'ab';
  const pick = chars => chars[Math.floor(rand() * chars.length)];
  const length = large ? 2000 : Math.floor(rand() * 7);
  let s = '';
  for (let i = 0; i < length; i++) s += pick(letters);
  if (!large && rand() < 0.4) {
    let p = '';
    const patternLength = Math.floor(rand() * 7);
    for (let i = 0; i < patternLength; i++) p += pick('ab?*');
    return [s, p];
  }
  // Build a pattern that matches s, then sometimes break it by changing one character.
  // Large patterns use long stars so the O(m * n) table stays small enough for the local judge.
  const starChance = large ? 0.4 : 0.15;
  const starRun = large ? 30 : 4;
  let p = '';
  let i = 0;
  while (i < s.length) {
    const r = rand();
    if (r < starChance) { p += '*'; i += Math.floor(rand() * starRun); }
    else if (r < starChance + 0.15) { p += '?'; i++; }
    else { p += s[i]; i++; }
  }
  if (rand() < 0.3) p += '*';
  if (p.length > 0 && rand() < 0.4) {
    const k = Math.floor(rand() * p.length);
    p = p.slice(0, k) + pick(letters) + p.slice(k + 1);
  }
  return [s, p.slice(0, 2000)];
}
